UPDATE house_races SET candidate1_name = 'C. Beck', candidate1_party = 'D'
WHERE state_code = 'OR' AND district = '2';

-- OR-4: R nominee is M. DeSpain (won 86.7%)
UPDATE house_races SET candidate2_name = 'M. DeSpain', candidate2_party = 'R'
WHERE state_code = 'OR' AND district = '4';

SELECT state_code, district, candidate1_name, candidate1_party, candidate2_name, candidate2_party 
FROM house_races WHERE state_code = 'OR' ORDER BY district;

